  "core/repositorio-datos.js": function(require, module, exports) {
const clasesIndex = require('../clases');
const subclasesIndex = require('../subclases');
const especiesIndex = require('../especies');
const trasfondosIndex = require('../trasfondos');
const dotes = require('../dotes');
const conjuros = require('../conjuros');
const equipo = require('../equipo');

function cargarDesdeIndice(indice, id, carpeta) {
  if (!indice || !indice[id]) return null;
  try { return require(`../${carpeta}/${indice[id]}`); }
  catch (_) { return null; }
}
function obtenerClase(id) { return cargarDesdeIndice(clasesIndex, id, 'clases'); }
function obtenerSubclase(id) { return cargarDesdeIndice(subclasesIndex, id, 'subclases'); }
function obtenerEspecie(id) { return cargarDesdeIndice(especiesIndex, id, 'especies'); }
function obtenerTrasfondo(id) { return cargarDesdeIndice(trasfondosIndex, id, 'trasfondos'); }
function obtenerDote(id) { return dotes[id] ?? null; }
function obtenerConjuro(id) { return conjuros[id] ?? null; }
function obtenerEquipo(id) {
  const plano = {
    ...equipo.catalogo.armas, ...equipo.catalogo.armaduras, ...equipo.catalogo.escudo,
    ...equipo.catalogo.herramientas, ...equipo.catalogo.aventurero, ...equipo.catalogo.pergaminos,
    ...equipo.catalogo.municion, ...equipo.catalogo.paquetes, ...equipo.catalogo.monturas,
    ...equipo.catalogo.arreos, ...equipo.catalogo.vehiculos
  };
  return plano[id] ?? null;
}
module.exports = { obtenerClase, obtenerSubclase, obtenerEspecie, obtenerTrasfondo, obtenerDote, obtenerConjuro, obtenerEquipo };

  },
  "core/servicio-personaje.js": function(require, module, exports) {
const { crearPersonajeBase } = require('../modelos/modelo-personaje');
const { crearCalculado } = require('../modelos/modelo-calculado');
const { crearEquipamiento } = require('../modelos/modelo-inventario');
const { obtenerClase, obtenerSubclase, obtenerEspecie, obtenerTrasfondo } = require('./repositorio-datos');
const { calcularBase } = require('../motor/motor-calculado');
const motorEquipo = require('../motor/motor-equipo');

function crearPersonaje(opciones = {}) {
  const personaje = crearPersonajeBase();
  personaje.id = opciones.id ?? null;
  personaje.identidad.nombre = opciones.nombre ?? '';
  personaje.identidad.jugador = opciones.jugador ?? '';
  personaje.base.nivel = Number.isInteger(opciones.nivel) ? opciones.nivel : 1;
  personaje.base.caracteristicas = { ...(opciones.caracteristicas || {}) };
  personaje.base.especie = opciones.especie ?? null;
  personaje.base.clase = opciones.clase ?? null;
  personaje.base.subclase = opciones.subclase ?? null;
  personaje.base.trasfondo = opciones.trasfondo ?? null;
  personaje.calculado = crearCalculado();
  personaje.estado.equipo = { inventario: [], equipamiento: crearEquipamiento() };
  recalcularBase(personaje);
  return personaje;
}

function validarOrigenes(personaje) {
  const errores = [];
  if (personaje.base.clase && !obtenerClase(personaje.base.clase)) errores.push('clase_no_existe');
  if (personaje.base.subclase && !obtenerSubclase(personaje.base.subclase)) errores.push('subclase_no_existe');
  if (personaje.base.especie && !obtenerEspecie(personaje.base.especie)) errores.push('especie_no_existe');
  if (personaje.base.trasfondo && !obtenerTrasfondo(personaje.base.trasfondo)) errores.push('trasfondo_no_existe');
  return errores;
}

function recalcularBase(personaje) {
  personaje.calculado = { ...personaje.calculado, ...calcularBase(personaje) };
  return personaje.calculado;
}

function sincronizarInventarioBase(personaje) {
  const inventario = personaje.estado?.equipo?.inventario || [];
  personaje.base.equipo = inventario.map(i => ({ ...i }));
  return personaje.base.equipo;
}

function agregarEquipo(personaje, objetoId, cantidad = 1, opciones = {}) {
  const resultado = motorEquipo.agregarObjeto(personaje, objetoId, cantidad, opciones);
  if (resultado.exitoso) sincronizarInventarioBase(personaje);
  return resultado;
}

function equiparEquipo(personaje, idInstancia, ranura = null) {
  const resultado = motorEquipo.equiparObjeto(personaje, idInstancia, ranura);
  if (resultado.exitoso) sincronizarInventarioBase(personaje);
  return resultado;
}

function desequiparEquipo(personaje, idInstancia) {
  const resultado = motorEquipo.desequiparObjeto(personaje, idInstancia);
  if (resultado.exitoso) sincronizarInventarioBase(personaje);
  return resultado;
}

module.exports = { crearPersonaje, validarOrigenes, recalcularBase, sincronizarInventarioBase, agregarEquipo, equiparEquipo, desequiparEquipo };

  },
